use filmcraft_project::{Project,ItemId,MediaRef};use filmcraft_time::{Tick,FrameRate};use filmcraft_media::{SharedSource,generators::GeneratorSource};use filmcraft_render::{render_sequence,RenderOptions};use serde_json::{Value,json};use std::sync::Arc;
fn main(){let input:Value=serde_json::from_slice(&std::fs::read(std::env::args().nth(1).unwrap()).unwrap()).unwrap();const T:i64=254016000000;let mut cases=vec![];
for profile in [0,5,10,15]{let base=&input["cases"][profile*6]["document"];for levels in [1,2,8,9]{for clock in 0..3{let mut doc=base.clone();let mut previous=6u64;
 for level in 1..=levels{let id=1000+level;let mut item=doc["project"]["items"]["6"].clone();item["id"]=json!(id);item["name"]=json!(format!("Nest {level}"));let seq=&mut item["kind"]["Sequence"];seq["caption_tracks"]=json!([]);let mut track=seq["video_tracks"][0].clone();track["id"]=json!(9000+level);track["transitions"]=json!([]);let mut clip=track["items"][0].clone();clip["id"]=json!(10000+level);clip["item"]=json!(previous);clip["start"]=json!(0);clip["duration"]=json!(10*T);clip["source_in"]=json!(0);clip["speed"]=json!(1.);clip["reverse"]=json!(false);clip["frame_hold"]=Value::Null;clip["effects"]=json!([]);
 if level==levels{clip["source_in"]=json!(T/7);clip["speed"]=json!(if clock==1{1.5}else{1.});clip["reverse"]=json!(clock==1);clip["frame_hold"]=if clock==2{json!(T/2)}else{Value::Null};clip["hold_filters"]=json!(false);clip["effects"]=json!([{"effect":"motion","enabled":true,"params":{"scale":{"value":{"Float":73.25}},"rotation":{"value":{"Float":9.25}}}},{"effect":"opacity","enabled":true,"params":{"opacity":{"value":{"Float":70.}}}}]);}
 track["items"]=json!([clip]);seq["video_tracks"]=json!([track]);doc["project"]["items"][id.to_string()]=item;previous=id;
 }
 let p:Project=serde_json::from_value(doc["project"].clone()).unwrap();let source=|id:ItemId|{let(_,media,_)=p.resolve_media(id)?;let MediaRef::Generator(generator)=&media.media else{return None};Some(Arc::new(GeneratorSource::new(generator.clone(),320,200,FrameRate::new(24,1),Tick(100*T)))as SharedSource)};
 for at in [0,T/2,T]{for scale in [1.,0.5]{let out=render_sequence(&p,ItemId(previous),Tick(at),RenderOptions{scale,captions:false,working_output:true,..Default::default()},&source);cases.push(json!({"document":doc,"sequence":previous,"at":at,"profile":profile,"levels":levels,"clock":clock,"scale":scale,"width":out.w,"height":out.h,"bits":out.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));}}
 }}}
 println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases}));}
